package com.codeduel.model;

public enum Role {
    ROLE_USER,
    ROLE_ADMIN
}

package com.codeduel.model;

public enum Difficulty {
    EASY,
    MEDIUM,
    HARD
}

package com.codeduel.model;

public enum Language {
    JAVA,
    PYTHON,
    CPP,
    JAVASCRIPT
}

package com.codeduel.model;

public enum MatchMode {
    SCORE,
    CLASSIC,
    SUDDEN_DEATH
}

package com.codeduel.model;

public enum SubmissionStatus {
    PENDING,
    COMPILING,
    RUNNING,
    COMPLETED,
    FAILED
}

package com.codeduel.model;

public enum SubmissionResult {
    ACCEPTED,
    WRONG_ANSWER,
    TIME_LIMIT_EXCEEDED,
    MEMORY_LIMIT_EXCEEDED,
    COMPILATION_ERROR,
    RUNTIME_ERROR
}

package com.codeduel.model;

import com.fasterxml.jackson.annotation.JsonIgnore;
import jakarta.persistence.*;
import java.time.LocalDateTime;

@Entity
@Table(name = "users", indexes = {
    @Index(name = "idx_user_username", columnList = "username", unique = true),
    @Index(name = "idx_user_email", columnList = "email", unique = true),
    @Index(name = "idx_user_rating", columnList = "rating")
})
public class User {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false, unique = true, length = 50)
    private String username;

    @Column(nullable = false, unique = true, length = 100)
    private String email;

    @JsonIgnore
    @Column(nullable = false)
    private String passwordHash;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private Role role = Role.ROLE_USER;

    @Column(nullable = false)
    private Integer rating = 1200;

    @Column(nullable = false)
    private Integer wins = 0;

    @Column(nullable = false)
    private Integer losses = 0;

    @Column(nullable = false)
    private Integer draws = 0;

    @Column(nullable = false)
    private Integer matchesPlayed = 0;

    @Column(nullable = false)
    private Integer winStreak = 0;

    @Column(nullable = false)
    private Integer bestWinStreak = 0;

    private Integer globalRank;

    @Column(nullable = false)
    private Long totalScore = 0L;

    @Column(nullable = false)
    private Boolean isBanned = false;

    @Column(nullable = false, updatable = false)
    private LocalDateTime createdAt = LocalDateTime.now();

    @Column(nullable = false)
    private LocalDateTime updatedAt = LocalDateTime.now();

    public User() {}

    public User(String username, String email, String passwordHash) {
        this.username = username;
        this.email = email;
        this.passwordHash = passwordHash;
        this.role = Role.ROLE_USER;
        this.rating = 1200;
        this.createdAt = LocalDateTime.now();
        this.updatedAt = LocalDateTime.now();
    }

    @PreUpdate
    public void onUpdate() {
        this.updatedAt = LocalDateTime.now();
    }

    public double getWinRate() {
        if (matchesPlayed == null || matchesPlayed == 0) return 0.0;
        return Math.round(((double) wins / matchesPlayed) * 1000.0) / 10.0;
    }

    // Getters and Setters
    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public String getUsername() { return username; }
    public void setUsername(String username) { this.username = username; }

    public String getEmail() { return email; }
    public void setEmail(String email) { this.email = email; }

    public String getPasswordHash() { return passwordHash; }
    public void setPasswordHash(String passwordHash) { this.passwordHash = passwordHash; }

    public Role getRole() { return role; }
    public void setRole(Role role) { this.role = role; }

    public Integer getRating() { return rating; }
    public void setRating(Integer rating) { this.rating = rating; }

    public Integer getWins() { return wins; }
    public void setWins(Integer wins) { this.wins = wins; }

    public Integer getLosses() { return losses; }
    public void setLosses(Integer losses) { this.losses = losses; }

    public Integer getDraws() { return draws; }
    public void setDraws(Integer draws) { this.draws = draws; }

    public Integer getMatchesPlayed() { return matchesPlayed; }
    public void setMatchesPlayed(Integer matchesPlayed) { this.matchesPlayed = matchesPlayed; }

    public Integer getWinStreak() { return winStreak; }
    public void setWinStreak(Integer winStreak) { this.winStreak = winStreak; }

    public Integer getBestWinStreak() { return bestWinStreak; }
    public void setBestWinStreak(Integer bestWinStreak) { this.bestWinStreak = bestWinStreak; }

    public Integer getGlobalRank() { return globalRank; }
    public void setGlobalRank(Integer globalRank) { this.globalRank = globalRank; }

    public Long getTotalScore() { return totalScore; }
    public void setTotalScore(Long totalScore) { this.totalScore = totalScore; }

    public Boolean getIsBanned() { return isBanned; }
    public void setIsBanned(Boolean isBanned) { this.isBanned = isBanned; }

    public LocalDateTime getCreatedAt() { return createdAt; }
    public void setCreatedAt(LocalDateTime createdAt) { this.createdAt = createdAt; }

    public LocalDateTime getUpdatedAt() { return updatedAt; }
    public void setUpdatedAt(LocalDateTime updatedAt) { this.updatedAt = updatedAt; }
}

package com.codeduel.model;

import com.fasterxml.jackson.annotation.JsonIgnore;
import jakarta.persistence.*;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;

@Entity
@Table(name = "problems", indexes = {
    @Index(name = "idx_problem_difficulty", columnList = "difficulty"),
    @Index(name = "idx_problem_slug", columnList = "slug", unique = true)
})
public class Problem {

    @Id
    @Column(name = "id", length = 32, nullable = false)
    private String id; // e.g. "CD-0001"

    @Column(nullable = false, length = 200)
    private String title;

    @Column(nullable = false, unique = true, length = 200)
    private String slug;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private Difficulty difficulty = Difficulty.MEDIUM;

    @Column(length = 500)
    private String topics; // comma separated: "Array,Hash Table"

    @Column(length = 500)
    private String patterns; // comma separated: "Two Pointers,Sliding Window"

    @Lob
    @Column(columnDefinition = "TEXT")
    private String description;

    @Lob
    @Column(columnDefinition = "TEXT")
    private String constraints;

    @Lob
    @Column(columnDefinition = "TEXT")
    private String examples; // JSON format

    @Lob
    @Column(columnDefinition = "TEXT")
    private String inputFormat;

    @Lob
    @Column(columnDefinition = "TEXT")
    private String outputFormat;

    @Column(nullable = false)
    private Integer timeLimitMs = 2000;

    @Column(nullable = false)
    private Integer memoryLimitMb = 256;

    @Column(length = 50)
    private String expectedTimeComplexity = "O(n)";

    @Column(length = 50)
    private String expectedSpaceComplexity = "O(1)";

    @Column(length = 100)
    private String source = "CodeDuel";

    @Column(length = 500)
    private String externalUrl;

    @Lob
    @Column(columnDefinition = "TEXT")
    private String starterCodeJava;

    @Lob
    @Column(columnDefinition = "TEXT")
    private String starterCodePython;

    @Lob
    @Column(columnDefinition = "TEXT")
    private String starterCodeCpp;

    @Lob
    @Column(columnDefinition = "TEXT")
    private String starterCodeJs;

    @Lob
    @Column(columnDefinition = "TEXT")
    private String solutionExplanation;

    @OneToMany(mappedBy = "problem", cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.LAZY)
    @JsonIgnore
    private List<TestCase> testCases = new ArrayList<>();

    @Column(nullable = false)
    private Boolean isActive = true;

    private Integer totalSubmissions = 0;
    private Integer acceptedSubmissions = 0;
    private Double avgRuntimeMs = 120.0;
    private Double avgMemoryMb = 28.0;

    @Column(nullable = false, updatable = false)
    private LocalDateTime createdAt = LocalDateTime.now();

    @Column(nullable = false)
    private LocalDateTime updatedAt = LocalDateTime.now();

    public Problem() {}

    public Problem(String id, String title, String slug, Difficulty difficulty, String topics, String description) {
        this.id = id;
        this.title = title;
        this.slug = slug;
        this.difficulty = difficulty;
        this.topics = topics;
        this.description = description;
        this.createdAt = LocalDateTime.now();
        this.updatedAt = LocalDateTime.now();
    }

    @PreUpdate
    public void onUpdate() {
        this.updatedAt = LocalDateTime.now();
    }

    public String getStarterCode(Language language) {
        if (language == null) return starterCodePython;
        return switch (language) {
            case JAVA -> starterCodeJava != null ? starterCodeJava : "// Java Starter Code\nclass Solution {\n    \n}";
            case PYTHON -> starterCodePython != null ? starterCodePython : "# Python 3 Starter Code\nclass Solution:\n    pass";
            case CPP -> starterCodeCpp != null ? starterCodeCpp : "// C++ Starter Code\n#include <iostream>\nusing namespace std;\nclass Solution {\npublic:\n    \n};";
            case JAVASCRIPT -> starterCodeJs != null ? starterCodeJs : "// JavaScript Starter Code\nfunction solution() {\n    \n}";
        };
    }

    // Getters & Setters
    public String getId() { return id; }
    public void setId(String id) { this.id = id; }

    public String getTitle() { return title; }
    public void setTitle(String title) { this.title = title; }

    public String getSlug() { return slug; }
    public void setSlug(String slug) { this.slug = slug; }

    public Difficulty getDifficulty() { return difficulty; }
    public void setDifficulty(Difficulty difficulty) { this.difficulty = difficulty; }

    public String getTopics() { return topics; }
    public void setTopics(String topics) { this.topics = topics; }

    public String getPatterns() { return patterns; }
    public void setPatterns(String patterns) { this.patterns = patterns; }

    public String getDescription() { return description; }
    public void setDescription(String description) { this.description = description; }

    public String getConstraints() { return constraints; }
    public void setConstraints(String constraints) { this.constraints = constraints; }

    public String getExamples() { return examples; }
    public void setExamples(String examples) { this.examples = examples; }

    public String getInputFormat() { return inputFormat; }
    public void setInputFormat(String inputFormat) { this.inputFormat = inputFormat; }

    public String getOutputFormat() { return outputFormat; }
    public void setOutputFormat(String outputFormat) { this.outputFormat = outputFormat; }

    public Integer getTimeLimitMs() { return timeLimitMs; }
    public void setTimeLimitMs(Integer timeLimitMs) { this.timeLimitMs = timeLimitMs; }

    public Integer getMemoryLimitMb() { return memoryLimitMb; }
    public void setMemoryLimitMb(Integer memoryLimitMb) { this.memoryLimitMb = memoryLimitMb; }

    public String getExpectedTimeComplexity() { return expectedTimeComplexity; }
    public void setExpectedTimeComplexity(String expectedTimeComplexity) { this.expectedTimeComplexity = expectedTimeComplexity; }

    public String getExpectedSpaceComplexity() { return expectedSpaceComplexity; }
    public void setExpectedSpaceComplexity(String expectedSpaceComplexity) { this.expectedSpaceComplexity = expectedSpaceComplexity; }

    public String getSource() { return source; }
    public void setSource(String source) { this.source = source; }

    public String getExternalUrl() { return externalUrl; }
    public void setExternalUrl(String externalUrl) { this.externalUrl = externalUrl; }

    public String getStarterCodeJava() { return starterCodeJava; }
    public void setStarterCodeJava(String starterCodeJava) { this.starterCodeJava = starterCodeJava; }

    public String getStarterCodePython() { return starterCodePython; }
    public void setStarterCodePython(String starterCodePython) { this.starterCodePython = starterCodePython; }

    public String getStarterCodeCpp() { return starterCodeCpp; }
    public void setStarterCodeCpp(String starterCodeCpp) { this.starterCodeCpp = starterCodeCpp; }

    public String getStarterCodeJs() { return starterCodeJs; }
    public void setStarterCodeJs(String starterCodeJs) { this.starterCodeJs = starterCodeJs; }

    public String getSolutionExplanation() { return solutionExplanation; }
    public void setSolutionExplanation(String solutionExplanation) { this.solutionExplanation = solutionExplanation; }

    public List<TestCase> getTestCases() { return testCases; }
    public void setTestCases(List<TestCase> testCases) { this.testCases = testCases; }

    public Boolean getIsActive() { return isActive; }
    public void setIsActive(Boolean isActive) { this.isActive = isActive; }

    public Integer getTotalSubmissions() { return totalSubmissions; }
    public void setTotalSubmissions(Integer totalSubmissions) { this.totalSubmissions = totalSubmissions; }

    public Integer getAcceptedSubmissions() { return acceptedSubmissions; }
    public void setAcceptedSubmissions(Integer acceptedSubmissions) { this.acceptedSubmissions = acceptedSubmissions; }

    public Double getAvgRuntimeMs() { return avgRuntimeMs; }
    public void setAvgRuntimeMs(Double avgRuntimeMs) { this.avgRuntimeMs = avgRuntimeMs; }

    public Double getAvgMemoryMb() { return avgMemoryMb; }
    public void setAvgMemoryMb(Double avgMemoryMb) { this.avgMemoryMb = avgMemoryMb; }

    public LocalDateTime getCreatedAt() { return createdAt; }
    public void setCreatedAt(LocalDateTime createdAt) { this.createdAt = createdAt; }

    public LocalDateTime getUpdatedAt() { return updatedAt; }
    public void setUpdatedAt(LocalDateTime updatedAt) { this.updatedAt = updatedAt; }
}

package com.codeduel.model;

import com.fasterxml.jackson.annotation.JsonIgnore;
import jakarta.persistence.*;
import java.time.LocalDateTime;

@Entity
@Table(name = "test_cases", indexes = {
    @Index(name = "idx_tc_problem", columnList = "problem_id")
})
public class TestCase {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "problem_id", nullable = false)
    @JsonIgnore
    private Problem problem;

    @Lob
    @Column(columnDefinition = "TEXT", nullable = false)
    private String inputData;

    @Lob
    @Column(columnDefinition = "TEXT", nullable = false)
    private String expectedOutput;

    @Column(nullable = false)
    private Boolean isHidden = false;

    @Lob
    @Column(columnDefinition = "TEXT")
    private String explanation;

    private Integer orderIndex = 0;

    @Column(nullable = false, updatable = false)
    private LocalDateTime createdAt = LocalDateTime.now();

    public TestCase() {}

    public TestCase(Problem problem, String inputData, String expectedOutput, Boolean isHidden, Integer orderIndex) {
        this.problem = problem;
        this.inputData = inputData;
        this.expectedOutput = expectedOutput;
        this.isHidden = isHidden;
        this.orderIndex = orderIndex;
        this.createdAt = LocalDateTime.now();
    }

    // Getters and Setters
    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public Problem getProblem() { return problem; }
    public void setProblem(Problem problem) { this.problem = problem; }

    public String getInputData() { return inputData; }
    public void setInputData(String inputData) { this.inputData = inputData; }

    public String getExpectedOutput() { return expectedOutput; }
    public void setExpectedOutput(String expectedOutput) { this.expectedOutput = expectedOutput; }

    public Boolean getIsHidden() { return isHidden; }
    public void setIsHidden(Boolean isHidden) { this.isHidden = isHidden; }

    public String getExplanation() { return explanation; }
    public void setExplanation(String explanation) { this.explanation = explanation; }

    public Integer getOrderIndex() { return orderIndex; }
    public void setOrderIndex(Integer orderIndex) { this.orderIndex = orderIndex; }

    public LocalDateTime getCreatedAt() { return createdAt; }
    public void setCreatedAt(LocalDateTime createdAt) { this.createdAt = createdAt; }
}

package com.codeduel.model;

import com.fasterxml.jackson.annotation.JsonIgnore;
import jakarta.persistence.*;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;

@Entity
@Table(name = "matches", indexes = {
    @Index(name = "idx_match_status", columnList = "status"),
    @Index(name = "idx_match_created", columnList = "createdAt")
})
public class Match {

    @Id
    @Column(length = 64, nullable = false)
    private String id;

    @ManyToOne(fetch = FetchType.EAGER)
    @JoinColumn(name = "problem_id", nullable = false)
    private Problem problem;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 30)
    private MatchStatus status = MatchStatus.WAITING;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 30)
    private MatchMode mode = MatchMode.SCORE;

    private LocalDateTime countdownStartTime;
    private LocalDateTime startTime;
    private LocalDateTime endTime;

    @Column(nullable = false)
    private Integer timeLimitSeconds = 900; // 15 minutes

    private Long winnerId;

    @Column(nullable = false)
    private Boolean isDraw = false;

    @OneToMany(mappedBy = "match", cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    private List<MatchPlayer> matchPlayers = new ArrayList<>();

    @Column(nullable = false, updatable = false)
    private LocalDateTime createdAt = LocalDateTime.now();

    @Column(nullable = false)
    private LocalDateTime updatedAt = LocalDateTime.now();

    public Match() {}

    public Match(String id, Problem problem, MatchMode mode, Integer timeLimitSeconds) {
        this.id = id;
        this.problem = problem;
        this.mode = mode != null ? mode : MatchMode.SCORE;
        this.timeLimitSeconds = timeLimitSeconds != null ? timeLimitSeconds : 900;
        this.status = MatchStatus.MATCHED;
        this.createdAt = LocalDateTime.now();
        this.updatedAt = LocalDateTime.now();
    }

    @PreUpdate
    public void onUpdate() {
        this.updatedAt = LocalDateTime.now();
    }

    // Getters and Setters
    public String getId() { return id; }
    public void setId(String id) { this.id = id; }

    public Problem getProblem() { return problem; }
    public void setProblem(Problem problem) { this.problem = problem; }

    public MatchStatus getStatus() { return status; }
    public void setStatus(MatchStatus status) { this.status = status; }

    public MatchMode getMode() { return mode; }
    public void setMode(MatchMode mode) { this.mode = mode; }

    public LocalDateTime getCountdownStartTime() { return countdownStartTime; }
    public void setCountdownStartTime(LocalDateTime countdownStartTime) { this.countdownStartTime = countdownStartTime; }

    public LocalDateTime getStartTime() { return startTime; }
    public void setStartTime(LocalDateTime startTime) { this.startTime = startTime; }

    public LocalDateTime getEndTime() { return endTime; }
    public void setEndTime(LocalDateTime endTime) { this.endTime = endTime; }

    public Integer getTimeLimitSeconds() { return timeLimitSeconds; }
    public void setTimeLimitSeconds(Integer timeLimitSeconds) { this.timeLimitSeconds = timeLimitSeconds; }

    public Long getWinnerId() { return winnerId; }
    public void setWinnerId(Long winnerId) { this.winnerId = winnerId; }

    public Boolean getIsDraw() { return isDraw; }
    public void setIsDraw(Boolean isDraw) { this.isDraw = isDraw; }

    public List<MatchPlayer> getMatchPlayers() { return matchPlayers; }
    public void setMatchPlayers(List<MatchPlayer> matchPlayers) { this.matchPlayers = matchPlayers; }

    public LocalDateTime getCreatedAt() { return createdAt; }
    public void setCreatedAt(LocalDateTime createdAt) { this.createdAt = createdAt; }

    public LocalDateTime getUpdatedAt() { return updatedAt; }
    public void setUpdatedAt(LocalDateTime updatedAt) { this.updatedAt = updatedAt; }
}

package com.codeduel.model;

import com.fasterxml.jackson.annotation.JsonIgnore;
import jakarta.persistence.*;
import java.time.LocalDateTime;

@Entity
@Table(name = "match_players", indexes = {
    @Index(name = "idx_mp_match_user", columnList = "match_id, user_id")
})
public class MatchPlayer {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "match_id", nullable = false)
    @JsonIgnore
    private Match match;

    @ManyToOne(fetch = FetchType.EAGER, optional = false)
    @JoinColumn(name = "user_id", nullable = false)
    private User user;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 30)
    private PlayerMatchStatus status = PlayerMatchStatus.CODING;

    @Column(nullable = false)
    private Integer score = 0;

    private Double efficiencyScore = 0.0;
    private Long executionTimeMs;
    private Double memoryUsageMb;
    private Integer submissionTimeSeconds;

    private Integer testsPassed = 0;
    private Integer totalTests = 0;

    private Integer ratingBefore;
    private Integer ratingAfter;
    private Integer ratingChange = 0;

    private LocalDateTime disconnectedAt;

    @Column(nullable = false, updatable = false)
    private LocalDateTime createdAt = LocalDateTime.now();

    public MatchPlayer() {}

    public MatchPlayer(Match match, User user, Integer ratingBefore) {
        this.match = match;
        this.user = user;
        this.ratingBefore = ratingBefore;
        this.status = PlayerMatchStatus.CODING;
        this.createdAt = LocalDateTime.now();
    }

    // Getters and Setters
    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public Match getMatch() { return match; }
    public void setMatch(Match match) { this.match = match; }

    public User getUser() { return user; }
    public void setUser(User user) { this.user = user; }

    public PlayerMatchStatus getStatus() { return status; }
    public void setStatus(PlayerMatchStatus status) { this.status = status; }

    public Integer getScore() { return score; }
    public void setScore(Integer score) { this.score = score; }

    public Double getEfficiencyScore() { return efficiencyScore; }
    public void setEfficiencyScore(Double efficiencyScore) { this.efficiencyScore = efficiencyScore; }

    public Long getExecutionTimeMs() { return executionTimeMs; }
    public void setExecutionTimeMs(Long executionTimeMs) { this.executionTimeMs = executionTimeMs; }

    public Double getMemoryUsageMb() { return memoryUsageMb; }
    public void setMemoryUsageMb(Double memoryUsageMb) { this.memoryUsageMb = memoryUsageMb; }

    public Integer getSubmissionTimeSeconds() { return submissionTimeSeconds; }
    public void setSubmissionTimeSeconds(Integer submissionTimeSeconds) { this.submissionTimeSeconds = submissionTimeSeconds; }

    public Integer getTestsPassed() { return testsPassed; }
    public void setTestsPassed(Integer testsPassed) { this.testsPassed = testsPassed; }

    public Integer getTotalTests() { return totalTests; }
    public void setTotalTests(Integer totalTests) { this.totalTests = totalTests; }

    public Integer getRatingBefore() { return ratingBefore; }
    public void setRatingBefore(Integer ratingBefore) { this.ratingBefore = ratingBefore; }

    public Integer getRatingAfter() { return ratingAfter; }
    public void setRatingAfter(Integer ratingAfter) { this.ratingAfter = ratingAfter; }

    public Integer getRatingChange() { return ratingChange; }
    public void setRatingChange(Integer ratingChange) { this.ratingChange = ratingChange; }

    public LocalDateTime getDisconnectedAt() { return disconnectedAt; }
    public void setDisconnectedAt(LocalDateTime disconnectedAt) { this.disconnectedAt = disconnectedAt; }

    public LocalDateTime getCreatedAt() { return createdAt; }
    public void setCreatedAt(LocalDateTime createdAt) { this.createdAt = createdAt; }
}

package com.codeduel.model;

import com.fasterxml.jackson.annotation.JsonIgnore;
import jakarta.persistence.*;
import java.time.LocalDateTime;

@Entity
@Table(name = "submissions", indexes = {
    @Index(name = "idx_sub_user", columnList = "user_id"),
    @Index(name = "idx_sub_problem", columnList = "problem_id"),
    @Index(name = "idx_sub_match", columnList = "match_id")
})
public class Submission {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.EAGER, optional = false)
    @JoinColumn(name = "user_id", nullable = false)
    private User user;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "match_id")
    @JsonIgnore
    private Match match;

    @ManyToOne(fetch = FetchType.EAGER, optional = false)
    @JoinColumn(name = "problem_id", nullable = false)
    private Problem problem;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private Language language;

    @Lob
    @Column(columnDefinition = "TEXT", nullable = false)
    private String sourceCode;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private SubmissionStatus status = SubmissionStatus.PENDING;

    @Enumerated(EnumType.STRING)
    @Column(length = 30)
    private SubmissionResult result;

    private Long executionTimeMs = 0L;
    private Double memoryUsageMb = 0.0;

    @Column(nullable = false)
    private Integer testsPassed = 0;

    @Column(nullable = false)
    private Integer totalTests = 0;

    private Double efficiencyScore = 0.0;

    @Column(length = 50)
    private String estimatedTimeComplexity;

    @Column(length = 50)
    private String estimatedSpaceComplexity;

    @Lob
    @Column(columnDefinition = "TEXT")
    private String compilerOutput;

    @Lob
    @Column(columnDefinition = "TEXT")
    private String errorDetails;

    @Column(nullable = false)
    private Boolean isPractice = false;

    @Column(nullable = false, updatable = false)
    private LocalDateTime submittedAt = LocalDateTime.now();

    public Submission() {}

    public Submission(User user, Match match, Problem problem, Language language, String sourceCode, Boolean isPractice) {
        this.user = user;
        this.match = match;
        this.problem = problem;
        this.language = language;
        this.sourceCode = sourceCode;
        this.isPractice = isPractice != null ? isPractice : false;
        this.status = SubmissionStatus.PENDING;
        this.submittedAt = LocalDateTime.now();
    }

    // Getters and Setters
    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public User getUser() { return user; }
    public void setUser(User user) { this.user = user; }

    public Match getMatch() { return match; }
    public void setMatch(Match match) { this.match = match; }

