        this.match = match;
        this.isSolved = isSolved != null ? isSolved : false;
        this.attemptsCount = 1;
        this.lastAttemptedAt = LocalDateTime.now();
        if (Boolean.TRUE.equals(this.isSolved)) {
            this.solvedAt = LocalDateTime.now();
