    private void seed1000Problems() {
        long currentCount = problemRepository.count();
        if (currentCount >= 1000) {
            log.info("Question bank already contains {} problems. Skipping seed.", currentCount);
            return;
        }

        log.info("Seeding 1,000 curated DSA questions into CodeDuel bank...");

        // Topic distributions:
        // Arrays & Hashing: 120
        // Two Pointers & Sliding Window: 80
        // Binary Search: 70
        // Strings: 70
        // Linked List: 60
        // Stack & Monotonic Stack: 60
        // Queue & Deque: 30
        // Trees & BST: 100
        // Heap / Priority Queue: 50
        // Greedy: 60
        // Backtracking: 40
        // Graphs: 120
        // Dynamic Programming: 130
        // Bit Manipulation: 40
        // Trie: 20
        // Advanced DS / Algorithms: 50
        // Total = 1000

        List<TopicBlueprint> blueprints = Arrays.asList(
                new TopicBlueprint("Arrays & Hashing", "Array,Hash Table", "Hashing,Prefix Sum,Frequency Maps,Kadane", 120, 30, 66, 24),
                new TopicBlueprint("Two Pointers & Sliding Window", "Array,Two Pointers,Sliding Window", "Two Pointers,Sliding Window", 80, 20, 44, 16),
                new TopicBlueprint("Binary Search", "Array,Binary Search", "Binary Search,Search Space Reduction", 70, 18, 38, 14),
                new TopicBlueprint("Strings", "String,Hash Table", "String Matching,Two Pointers,Frequency", 70, 20, 38, 12),
                new TopicBlueprint("Linked List", "Linked List,Two Pointers", "Fast & Slow Pointers,Reversal,Merge", 60, 18, 32, 10),
                new TopicBlueprint("Stack & Monotonic Stack", "Stack,Monotonic Stack", "Monotonic Stack,Parentheses,Evaluation", 60, 16, 32, 12),
                new TopicBlueprint("Queue & Deque", "Queue,Deque,Sliding Window", "Monotonic Queue,BFS Queue,Circular Buffer", 30, 8, 16, 6),
                new TopicBlueprint("Trees & BST", "Tree,Binary Tree,Binary Search Tree", "DFS,BFS,Recursion,Tree DP", 100, 25, 55, 20),
                new TopicBlueprint("Heap / Priority Queue", "Heap (Priority Queue),Array", "Top K Elements,K-Way Merge,Min-Max Heap", 50, 12, 28, 10),
                new TopicBlueprint("Greedy", "Greedy,Sorting,Array", "Greedy Choice,Interval Scheduling,Partitioning", 60, 15, 33, 12),
                new TopicBlueprint("Backtracking", "Backtracking,Recursion", "State Exploration,Pruning,Permutations", 40, 8, 22, 10),
                new TopicBlueprint("Graphs", "Graph,Breadth-First Search,Depth-First Search,Union Find", "BFS,DFS,Dijkstra,Topological Sort,DSU,MST", 120, 26, 68, 26),
                new TopicBlueprint("Dynamic Programming", "Dynamic Programming", "1D DP,2D DP,Knapsack,Subsequence DP,Grid DP", 130, 24, 72, 34),
                new TopicBlueprint("Bit Manipulation", "Bit Manipulation,Math", "Bitwise XOR,Bit Masking,Bit Counting", 40, 12, 20, 8),
                new TopicBlueprint("Trie", "Trie,String,Design", "Prefix Tree,Bitwise Trie,Autocomplete", 20, 4, 12, 4),
                new TopicBlueprint("Advanced Data Structures & Algorithms", "Segment Tree,Binary Indexed Tree,Graph,Math", "Range Queries,Flow,Matrix Exponentiation", 50, 4, 26, 20)
        );

        int problemCounter = 1;
        List<Problem> problemBatch = new ArrayList<>();
        List<TestCase> testCaseBatch = new ArrayList<>();

        for (TopicBlueprint bp : blueprints) {
            int easyAllocated = 0;
            int medAllocated = 0;
            int hardAllocated = 0;

            for (int i = 1; i <= bp.totalCount; i++) {
                String problemId = String.format("CD-%04d", problemCounter);
                Difficulty diff;
                if (easyAllocated < bp.easyCount) {
                    diff = Difficulty.EASY;
                    easyAllocated++;
                } else if (medAllocated < bp.mediumCount) {
                    diff = Difficulty.MEDIUM;
                    medAllocated++;
                } else {
                    diff = Difficulty.HARD;
                    hardAllocated++;
                }

                String title = getCuratedProblemTitle(bp.category, i, diff);
                String slug = title.toLowerCase().replaceAll("[^a-z0-9]+", "-").replaceAll("^-|-$", "") + "-" + problemCounter;

                Problem problem = new Problem();
                problem.setId(problemId);
                problem.setTitle(title);
                problem.setSlug(slug);
                problem.setDifficulty(diff);
                problem.setTopics(bp.topics);
                problem.setPatterns(bp.patterns);
                problem.setDescription(generateProblemDescription(title, bp.category, diff));
                problem.setConstraints(generateConstraints(diff));
                problem.setExamples(generateExamples(title, bp.category));
                problem.setInputFormat("First line contains standard formatted inputs as specified in the problem statement.");
                problem.setOutputFormat("Return or print the expected answer format.");
                problem.setTimeLimitMs(diff == Difficulty.HARD ? 3000 : 2000);
                problem.setMemoryLimitMb(256);
