package com.codeduel.service;

import com.codeduel.dto.ProblemDto;
import com.codeduel.exception.ResourceNotFoundException;
import com.codeduel.model.Difficulty;
import com.codeduel.model.Problem;
import com.codeduel.model.UserProblemHistory;
import com.codeduel.repository.ProblemRepository;
import com.codeduel.repository.UserProblemHistoryRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.*;

@Service
public class ProblemService {

    private static final Logger log = LoggerFactory.getLogger(ProblemService.class);

    private final ProblemRepository problemRepository;
    private final UserProblemHistoryRepository userProblemHistoryRepository;
    private final Random random = new Random();

    public ProblemService(ProblemRepository problemRepository, UserProblemHistoryRepository userProblemHistoryRepository) {
        this.problemRepository = problemRepository;
        this.userProblemHistoryRepository = userProblemHistoryRepository;
    }

    @Transactional(readOnly = true)
    public Page<ProblemDto> getFilteredProblems(Difficulty difficulty, String topic, String search, Pageable pageable, Long currentUserId) {
        Page<Problem> problems = problemRepository.findFilteredProblems(difficulty, topic, search, pageable);

        Set<String> solvedProblemIds = new HashSet<>();
        if (currentUserId != null) {
            solvedProblemIds.addAll(userProblemHistoryRepository.findSolvedProblemIdsByUserId(currentUserId));
        }

        return problems.map(p -> {
            ProblemDto dto = ProblemDto.fromEntity(p, false);
            dto.setIsSolvedByMe(solvedProblemIds.contains(p.getId()));
            return dto;
        });
    }

    @Transactional(readOnly = true)
    public ProblemDto getProblemDtoById(String id, Long currentUserId) {
        Problem problem = problemRepository.findById(id)
                .orElseThrow(() -> new ResourceNotFoundException("Problem not found with id: " + id));

        ProblemDto dto = ProblemDto.fromEntity(problem, true);
        if (currentUserId != null) {
            Optional<UserProblemHistory> history = userProblemHistoryRepository.findByUserIdAndProblemId(currentUserId, id);
            history.ifPresent(uph -> {
                dto.setIsSolvedByMe(uph.getIsSolved());
                dto.setMyBestRuntimeMs(uph.getBestRuntimeMs());
            });
        }
        return dto;
    }

    @Transactional(readOnly = true)
    public Problem selectProblemForMatch(Long player1Id, Long player2Id, Difficulty preferredDifficulty, String preferredTopic, int avgRating) {
        Difficulty targetDifficulty = preferredDifficulty;
        if (targetDifficulty == null) {
            if (avgRating < 1200) {
                targetDifficulty = Difficulty.EASY;
            } else if (avgRating <= 1650) {
                targetDifficulty = random.nextBoolean() ? Difficulty.EASY : Difficulty.MEDIUM;
            } else if (avgRating <= 2000) {
                targetDifficulty = Difficulty.MEDIUM;
            } else {
                targetDifficulty = random.nextBoolean() ? Difficulty.MEDIUM : Difficulty.HARD;
            }
        }

        // Get played problem IDs for both players to avoid repetition
        List<String> played1 = player1Id != null ? userProblemHistoryRepository.findPlayedProblemIdsByUserId(player1Id) : Collections.emptyList();
        List<String> played2 = player2Id != null ? userProblemHistoryRepository.findPlayedProblemIdsByUserId(player2Id) : Collections.emptyList();
        Set<String> excludedIds = new HashSet<>(played1);
        excludedIds.addAll(played2);

        List<Problem> candidates;
        if (!excludedIds.isEmpty()) {
            candidates = problemRepository.findByDifficultyAndIdNotIn(targetDifficulty, new ArrayList<>(excludedIds));
            if (candidates.isEmpty()) {
                // If specific difficulty unplayed pool is exhausted, try any unplayed difficulty
                candidates = problemRepository.findByIdNotIn(new ArrayList<>(excludedIds));
            }
        } else {
            candidates = problemRepository.findByDifficultyAndIsActiveTrue(targetDifficulty);
        }

        if (candidates == null || candidates.isEmpty()) {
            // Fallback to all active problems for this difficulty
            candidates = problemRepository.findByDifficultyAndIsActiveTrue(targetDifficulty);
        }

        if (candidates.isEmpty()) {
            candidates = problemRepository.findAll();
        }

        if (candidates.isEmpty()) {
            throw new ResourceNotFoundException("No problems available in question bank.");
        }

        // Filter by topic if requested and matches exist
        if (preferredTopic != null && !preferredTopic.isBlank()) {
            List<Problem> topicFiltered = candidates.stream()
                    .filter(p -> p.getTopics() != null && p.getTopics().toLowerCase().contains(preferredTopic.toLowerCase()))
                    .toList();
            if (!topicFiltered.isEmpty()) {
                candidates = topicFiltered;
            }
        }

        return candidates.get(random.nextInt(candidates.size()));
    }
}

package com.codeduel.service;

import com.codeduel.model.Match;
import com.codeduel.model.RatingHistory;
import com.codeduel.model.User;
import com.codeduel.repository.RatingHistoryRepository;
import com.codeduel.repository.UserRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class EloRatingService {

    private static final Logger log = LoggerFactory.getLogger(EloRatingService.class);

    private final UserRepository userRepository;
    private final RatingHistoryRepository ratingHistoryRepository;
    private final LeaderboardService leaderboardService;

    public EloRatingService(UserRepository userRepository,
                            RatingHistoryRepository ratingHistoryRepository,
                            LeaderboardService leaderboardService) {
        this.userRepository = userRepository;
        this.ratingHistoryRepository = ratingHistoryRepository;
        this.leaderboardService = leaderboardService;
    }

    public static class RatingDelta {
        public final int player1Change;
        public final int player2Change;
        public final int player1NewRating;
        public final int player2NewRating;

        public RatingDelta(int p1Change, int p2Change, int p1New, int p2New) {
            this.player1Change = p1Change;
            this.player2Change = p2Change;
            this.player1NewRating = p1New;
            this.player2NewRating = p2New;
        }
    }

    public int getKFactor(User user) {
        int matches = user.getMatchesPlayed() != null ? user.getMatchesPlayed() : 0;
        int rating = user.getRating() != null ? user.getRating() : 1200;

        if (matches < 10) return 40;
        if (rating < 1600) return 32;
        if (rating < 2000) return 24;
        return 16;
    }

    public double getExpectedScore(int playerRating, int opponentRating) {
        return 1.0 / (1.0 + Math.pow(10.0, (double) (opponentRating - playerRating) / 400.0));
    }

    public RatingDelta calculateElo(User p1, User p2, double scoreP1) {
        int r1 = p1.getRating();
        int r2 = p2.getRating();

        double expected1 = getExpectedScore(r1, r2);
        double expected2 = getExpectedScore(r2, r1);

        double scoreP2 = 1.0 - scoreP1;

        int k1 = getKFactor(p1);
        int k2 = getKFactor(p2);

        int delta1 = (int) Math.round(k1 * (scoreP1 - expected1));
        int delta2 = (int) Math.round(k2 * (scoreP2 - expected2));

        // Ensure at least +1 / -1 on decisive win
        if (scoreP1 == 1.0 && delta1 <= 0) delta1 = 1;
        if (scoreP2 == 1.0 && delta2 <= 0) delta2 = 1;
        if (scoreP1 == 0.0 && delta1 >= 0) delta1 = -1;
        if (scoreP2 == 0.0 && delta2 >= 0) delta2 = -1;

        int newR1 = Math.max(100, r1 + delta1);
        int newR2 = Math.max(100, r2 + delta2);

        return new RatingDelta(delta1, delta2, newR1, newR2);
    }

    @Transactional
    public RatingDelta applyMatchRating(User p1, User p2, Match match, Long winnerId, boolean isDraw) {
        double scoreP1 = isDraw ? 0.5 : (p1.getId().equals(winnerId) ? 1.0 : 0.0);
        RatingDelta delta = calculateElo(p1, p2, scoreP1);

        int oldR1 = p1.getRating();
        int oldR2 = p2.getRating();

        // Update User 1
        p1.setRating(delta.player1NewRating);
        p1.setMatchesPlayed(p1.getMatchesPlayed() + 1);
        if (isDraw) {
            p1.setDraws(p1.getDraws() + 1);
            p1.setWinStreak(0);
        } else if (p1.getId().equals(winnerId)) {
            p1.setWins(p1.getWins() + 1);
            p1.setWinStreak(p1.getWinStreak() + 1);
            p1.setBestWinStreak(Math.max(p1.getBestWinStreak(), p1.getWinStreak()));
        } else {
            p1.setLosses(p1.getLosses() + 1);
            p1.setWinStreak(0);
        }

        // Update User 2
        p2.setRating(delta.player2NewRating);
        p2.setMatchesPlayed(p2.getMatchesPlayed() + 1);
        if (isDraw) {
            p2.setDraws(p2.getDraws() + 1);
            p2.setWinStreak(0);
        } else if (p2.getId().equals(winnerId)) {
            p2.setWins(p2.getWins() + 1);
            p2.setWinStreak(p2.getWinStreak() + 1);
            p2.setBestWinStreak(Math.max(p2.getBestWinStreak(), p2.getWinStreak()));
        } else {
            p2.setLosses(p2.getLosses() + 1);
            p2.setWinStreak(0);
        }

        userRepository.save(p1);
        userRepository.save(p2);

        // Record history
        ratingHistoryRepository.save(new RatingHistory(p1, match, oldR1, delta.player1NewRating, delta.player1Change, oldR2, p2.getUsername()));
        ratingHistoryRepository.save(new RatingHistory(p2, match, oldR2, delta.player2NewRating, delta.player2Change, oldR1, p1.getUsername()));

        // Sync Redis leaderboard
        leaderboardService.updateUserRating(p1.getId(), delta.player1NewRating);
        leaderboardService.updateUserRating(p2.getId(), delta.player2NewRating);

        log.info("Elo updated for match {}: {} ({} -> {} [{}]), {} ({} -> {} [{}])",
                match.getId(), p1.getUsername(), oldR1, delta.player1NewRating, delta.player1Change,
                p2.getUsername(), oldR2, delta.player2NewRating, delta.player2Change);

        return delta;
    }
}

package com.codeduel.service;

import com.codeduel.dto.LeaderboardEntryDto;
import com.codeduel.model.User;
import com.codeduel.repository.UserRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.List;

@Service
public class LeaderboardService {

    private static final Logger log = LoggerFactory.getLogger(LeaderboardService.class);
    private static final String LEADERBOARD_KEY = "leaderboard:global";

    private final UserRepository userRepository;
    private final StringRedisTemplate redisTemplate;

    public LeaderboardService(UserRepository userRepository, StringRedisTemplate redisTemplate) {
        this.userRepository = userRepository;
        this.redisTemplate = redisTemplate;
    }

    public void updateUserRating(Long userId, int rating) {
        try {
            if (redisTemplate != null) {
                redisTemplate.opsForZSet().add(LEADERBOARD_KEY, userId.toString(), rating);
            }
        } catch (Exception ex) {
            log.warn("Could not update rating in Redis (falling back to MySQL): {}", ex.getMessage());
        }
    }

    public Integer getUserRank(Long userId) {
        if (userId == null) return null;
        try {
            if (redisTemplate != null) {
                Long rank = redisTemplate.opsForZSet().reverseRank(LEADERBOARD_KEY, userId.toString());
                if (rank != null) {
                    return (int) (rank + 1);
                }
            }
        } catch (Exception ex) {
            log.debug("Redis rank lookup fallback to MySQL: {}", ex.getMessage());
        }

        User user = userRepository.findById(userId).orElse(null);
        if (user == null) return 1;
        return userRepository.countRankByRating(user.getRating());
    }

    public List<LeaderboardEntryDto> getTopLeaderboard(int limit) {
        List<User> topUsers = userRepository.findAllByOrderByRatingDesc(PageRequest.of(0, Math.min(100, limit))).getContent();
        List<LeaderboardEntryDto> entries = new ArrayList<>();

        int rank = 1;
        for (User u : topUsers) {
            entries.add(new LeaderboardEntryDto(
                    rank++,
                    u.getId(),
                    u.getUsername(),
                    u.getRating(),
                    u.getWins(),
                    u.getLosses(),
                    u.getDraws(),
                    u.getMatchesPlayed(),
                    u.getWinStreak()
            ));
        }

        return entries;
    }
}

package com.codeduel.service;

import com.codeduel.dto.*;
import com.codeduel.model.*;
import com.codeduel.repository.*;
import org.springframework.data.domain.PageRequest;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

@Service
public class AnalyticsService {

    private final UserRepository userRepository;
    private final RatingHistoryRepository ratingHistoryRepository;
    private final UserProblemHistoryRepository userProblemHistoryRepository;
    private final UserAchievementRepository userAchievementRepository;
    private final SubmissionRepository submissionRepository;
    private final MatchRepository matchRepository;

    public AnalyticsService(UserRepository userRepository,
                            RatingHistoryRepository ratingHistoryRepository,
                            UserProblemHistoryRepository userProblemHistoryRepository,
                            UserAchievementRepository userAchievementRepository,
                            SubmissionRepository submissionRepository,
                            MatchRepository matchRepository) {
        this.userRepository = userRepository;
        this.ratingHistoryRepository = ratingHistoryRepository;
        this.userProblemHistoryRepository = userProblemHistoryRepository;
        this.userAchievementRepository = userAchievementRepository;
        this.submissionRepository = submissionRepository;
        this.matchRepository = matchRepository;
    }

    @Transactional(readOnly = true)
    public UserProfileDto getUserProfile(Long userId) {
        User user = userRepository.findById(userId).orElse(null);
        if (user == null) return null;

        UserProfileDto profile = new UserProfileDto();
        profile.setUser(UserDto.fromEntity(user));

        // Rating history
        List<RatingHistory> history = ratingHistoryRepository.findByUserIdOrderByCreatedAtAsc(userId);
        history.forEach(rh -> profile.getRatingHistory().add(RatingHistoryDto.fromEntity(rh)));

        // Problem counts
        profile.setSolvedProblemsCount(userProblemHistoryRepository.countByUserIdAndIsSolvedTrue(userId));
        profile.setAttemptedProblemsCount(userProblemHistoryRepository.countByUserId(userId));
        profile.setAcceptedSubmissionsCount(submissionRepository.countAcceptedByUserId(userId));

        // Topic mastery and difficulty breakdown
        Map<String, Integer> topicMap = new HashMap<>();
        Map<String, Integer> diffMap = new HashMap<>();
        diffMap.put("EASY", 0);
        diffMap.put("MEDIUM", 0);
        diffMap.put("HARD", 0);

        List<UserProblemHistory> solvedList = userProblemHistoryRepository.findByUserIdAndIsSolvedTrue(userId);
        for (UserProblemHistory uph : solvedList) {
            Problem p = uph.getProblem();
            if (p != null) {
                if (p.getDifficulty() != null) {
                    diffMap.put(p.getDifficulty().name(), diffMap.getOrDefault(p.getDifficulty().name(), 0) + 1);
                }
                if (p.getTopics() != null) {
                    String[] topics = p.getTopics().split(",");
                    for (String t : topics) {
                        String clean = t.trim();
                        if (!clean.isEmpty()) {
                            topicMap.put(clean, topicMap.getOrDefault(clean, 0) + 1);
                        }
                    }
                }
            }
        }
        profile.setTopicMastery(topicMap);
        profile.setDifficultyStats(diffMap);

        // Achievements
        List<UserAchievement> userAchievements = userAchievementRepository.findByUserId(userId);
        userAchievements.forEach(ua -> profile.getAchievements().add(UserAchievementDto.fromEntity(ua)));

        return profile;
    }

    @Transactional(readOnly = true)
    public PostMatchAnalysisDto generatePostMatchAnalysis(Match match, Long currentUserId) {
        PostMatchAnalysisDto dto = new PostMatchAnalysisDto();
        Problem problem = match.getProblem();
        if (problem == null) return dto;

        dto.setProblemId(problem.getId());
        dto.setProblemTitle(problem.getTitle());
        dto.setExpectedTimeComplexity(problem.getExpectedTimeComplexity());
        dto.setExpectedSpaceComplexity(problem.getExpectedSpaceComplexity());
        dto.setAvgProblemRuntimeMs(problem.getAvgRuntimeMs());
        dto.setAvgProblemMemoryMb(problem.getAvgMemoryMb());

        MatchPlayer myPlayer = null;
        MatchPlayer oppPlayer = null;

        for (MatchPlayer mp : match.getMatchPlayers()) {
            if (mp.getUser().getId().equals(currentUserId)) {
                myPlayer = mp;
            } else {
                oppPlayer = mp;
            }
        }

        if (myPlayer != null) {
            dto.setMyRuntimeMs(myPlayer.getExecutionTimeMs() != null ? myPlayer.getExecutionTimeMs() : 0L);
            dto.setMyMemoryMb(myPlayer.getMemoryUsageMb() != null ? myPlayer.getMemoryUsageMb() : 0.0);
            dto.setMyEfficiencyScore(myPlayer.getEfficiencyScore() != null ? myPlayer.getEfficiencyScore() : 0.0);
            dto.setMyScore(myPlayer.getScore() != null ? myPlayer.getScore() : 0);

            // Percentile calculation
            Long slowerCount = submissionRepository.countSlowerAcceptedSubmissions(problem.getId(), dto.getMyRuntimeMs());
            Long totalAccepted = submissionRepository.countTotalAcceptedSubmissions(problem.getId());
            if (totalAccepted != null && totalAccepted > 0) {
                double pct = Math.round(((double) slowerCount / totalAccepted) * 1000.0) / 10.0;
                dto.setMyRuntimePercentile(pct);
            } else {
                dto.setMyRuntimePercentile(78.5); // Baseline
            }
            dto.setMyMemoryPercentile(82.0);
        }

        if (oppPlayer != null) {
            dto.setOpponentRuntimeMs(oppPlayer.getExecutionTimeMs() != null ? oppPlayer.getExecutionTimeMs() : 0L);
            dto.setOpponentMemoryMb(oppPlayer.getMemoryUsageMb() != null ? oppPlayer.getMemoryUsageMb() : 0.0);
            dto.setOpponentEfficiencyScore(oppPlayer.getEfficiencyScore() != null ? oppPlayer.getEfficiencyScore() : 0.0);
            dto.setOpponentScore(oppPlayer.getScore() != null ? oppPlayer.getScore() : 0);
        }

        // Suggestions
        dto.getOptimizationTips().add("Your solution executed within the top tier threshold.");
        dto.getOptimizationTips().add("Expected complexity is " + problem.getExpectedTimeComplexity() + ". Memory usage is well bounded.");

        return dto;
    }
}

package com.codeduel.service;

import com.codeduel.dto.ProblemDto;
import com.codeduel.model.Difficulty;
import com.codeduel.model.Problem;
import com.codeduel.model.User;
import com.codeduel.repository.ProblemRepository;
import com.codeduel.repository.UserProblemHistoryRepository;
import com.codeduel.repository.UserRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.*;

@Service
public class ProblemRecommendationService {

    private final ProblemRepository problemRepository;
    private final UserProblemHistoryRepository userProblemHistoryRepository;
    private final UserRepository userRepository;

    public static class RecommendationDto {
        private ProblemDto problem;
        private String reason;

        public RecommendationDto(ProblemDto problem, String reason) {
            this.problem = problem;
            this.reason = reason;
        }

        public ProblemDto getProblem() { return problem; }
        public String getReason() { return reason; }
    }

    public ProblemRecommendationService(ProblemRepository problemRepository,
                                        UserProblemHistoryRepository userProblemHistoryRepository,
                                        UserRepository userRepository) {
        this.problemRepository = problemRepository;
        this.userProblemHistoryRepository = userProblemHistoryRepository;
        this.userRepository = userRepository;
    }

    @Transactional(readOnly = true)
    public List<RecommendationDto> getRecommendationsForUser(Long userId) {
        List<RecommendationDto> recommendations = new ArrayList<>();
        User user = userRepository.findById(userId).orElse(null);
        if (user == null) return recommendations;

        List<String> playedIds = userProblemHistoryRepository.findPlayedProblemIdsByUserId(userId);
        Set<String> playedSet = new HashSet<>(playedIds);

        int rating = user.getRating();
        Difficulty recommendedDiff = rating < 1400 ? Difficulty.EASY : (rating < 1800 ? Difficulty.MEDIUM : Difficulty.HARD);

        // Weak topics to target
        String[] targetTopics = {"Dynamic Programming", "Graphs", "Binary Search", "Two Pointers", "Trees & BST"};
        String[] reasons = {
                "Target your Dynamic Programming pattern mastery to boost your rating.",
                "Reinforce Graph BFS & DFS traversal fundamentals for upcoming duels.",
                "Sharpen your Binary Search range deduction speed under match pressure.",
                "Master Two Pointers & Sliding Window techniques for quick sub-2-minute solves.",
                "Practice Tree DP and recursion structures frequently used in competitive matches."
        };

        int idx = 0;
        for (String topic : targetTopics) {
            List<Problem> topicProblems = problemRepository.findByTopicsContainingIgnoreCaseAndIsActiveTrue(topic);
            for (Problem p : topicProblems) {
                if (!playedSet.contains(p.getId()) && (p.getDifficulty() == recommendedDiff || p.getDifficulty() == Difficulty.MEDIUM)) {
                    recommendations.add(new RecommendationDto(ProblemDto.fromEntity(p, false), reasons[idx % reasons.length]));
                    playedSet.add(p.getId());
                    break;
                }
            }
            idx++;
            if (recommendations.size() >= 4) break;
        }

        // If not enough, pick unplayed
        if (recommendations.size() < 3) {
            List<Problem> general = problemRepository.findByDifficultyAndIsActiveTrue(recommendedDiff);
            for (Problem p : general) {
                if (!playedSet.contains(p.getId())) {
                    recommendations.add(new RecommendationDto(ProblemDto.fromEntity(p, false), "Curated " + p.getDifficulty() + " problem to refine your match speed."));
                    playedSet.add(p.getId());
                    if (recommendations.size() >= 4) break;
                }
            }
        }

        return recommendations;
    }
}

