package com.codeduel;

import com.codeduel.judge.EfficiencyEngine;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

public class EfficiencyEngineTest {

    private EfficiencyEngine engine;

    @BeforeEach
    void setUp() {
        engine = new EfficiencyEngine();
    }

    @Test
    void testAntiJitterTolerance() {
        // 102ms vs 105ms should produce almost zero scoring difference (< 0.5 points)
        double score1 = engine.calculateEfficiency(102, 22.0, 2000, 256);
        double score2 = engine.calculateEfficiency(105, 22.0, 2000, 256);

        assertTrue(Math.abs(score1 - score2) <= 0.5, "Minor hardware jitter (102ms vs 105ms) must produce negligible score difference");
    }

    @Test
    void testFastSolutionScoresHigherThanSlow() {
        double fastScore = engine.calculateEfficiency(50, 18.0, 2000, 256);
        double slowScore = engine.calculateEfficiency(1800, 200.0, 2000, 256);

        assertTrue(fastScore > slowScore, "Fast solution should score substantially higher than near-timeout solution");
    }

    @Test
    void testMatchScoreHierarchyCorrectnessDominates() {
        // Accepted solution with moderate runtime
        int acceptedScore = engine.calculateMatchScore(true, 5, 5, 120, 24.0, 2000, 256, 300, 900);

        // Failed solution (3/5 tests) even with super fast runtime
        int failedScore = engine.calculateMatchScore(false, 3, 5, 10, 10.0, 2000, 256, 50, 900);

        assertTrue(acceptedScore >= 600, "Accepted solution score must be >= 600");
        assertTrue(failedScore < 300, "Failed solution score must be < 300");
        assertTrue(acceptedScore > failedScore, "Accepted solution must beat failed solution regardless of speed");
    }
}

package com.codeduel;

import com.codeduel.model.User;
import com.codeduel.service.EloRatingService;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

public class EloRatingServiceTest {

    private EloRatingService eloService;

    @BeforeEach
    void setUp() {
        eloService = new EloRatingService(null, null, null);
    }

    @Test
    void testExpectedScoreSymmetry() {
        double exp1 = eloService.getExpectedScore(1500, 1500);
        double exp2 = eloService.getExpectedScore(1500, 1500);

        assertEquals(0.5, exp1, 0.001);
        assertEquals(0.5, exp2, 0.001);
    }

    @Test
    void testHigherRatedHasHigherExpectedScore() {
        double expHigh = eloService.getExpectedScore(1800, 1400);
        double expLow = eloService.getExpectedScore(1400, 1800);

        assertTrue(expHigh > 0.90, "1800 vs 1400 should have high expected score");
        assertTrue(expLow < 0.10, "1400 vs 1800 should have low expected score");
        assertEquals(1.0, expHigh + expLow, 0.001);
    }

    @Test
    void testEqualRatingWinDelta() {
        User p1 = new User("p1", "p1@test.com", "hash");
        p1.setRating(1500);
        p1.setMatchesPlayed(20);

        User p2 = new User("p2", "p2@test.com", "hash");
        p2.setRating(1500);
        p2.setMatchesPlayed(20);

        EloRatingService.RatingDelta delta = eloService.calculateElo(p1, p2, 1.0); // p1 wins

        assertEquals(16, delta.player1Change, "Equal rating win with K=32 should give +16");
        assertEquals(-16, delta.player2Change, "Equal rating loss with K=32 should give -16");
        assertEquals(1516, delta.player1NewRating);
        assertEquals(1484, delta.player2NewRating);
    }

    @Test
    void testUnderdogWinGivesHigherDelta() {
        User underdog = new User("underdog", "u@test.com", "hash");
        underdog.setRating(1300);
        underdog.setMatchesPlayed(25);

        User favorite = new User("favorite", "f@test.com", "hash");
        favorite.setRating(1700);
        favorite.setMatchesPlayed(25);

        EloRatingService.RatingDelta delta = eloService.calculateElo(underdog, favorite, 1.0);

        assertTrue(delta.player1Change >= 25, "Underdog beating favorite should give large positive rating gain");
    }
}

package com.codeduel;

import com.codeduel.judge.ComplexityEstimator;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

public class ComplexityEstimatorTest {

    private ComplexityEstimator estimator;

    @BeforeEach
    void setUp() {
        estimator = new ComplexityEstimator();
    }

    @Test
    void testLinearComplexityDetection() {
        String linearCode = """
            public int[] solve(int[] nums, int target) {
                Map<Integer, Integer> map = new HashMap<>();
                for (int i = 0; i < nums.length; i++) {
                    int complement = target - nums[i];
                    if (map.containsKey(complement)) return new int[]{map.get(complement), i};
                    map.put(nums[i], i);
                }
                return new int[]{};
            }
            """;
        ComplexityEstimator.ComplexityAnalysis analysis = estimator.estimateComplexity(linearCode, "JAVA");
        assertEquals("O(n)", analysis.getEstimatedTimeComplexity());
        assertEquals("O(n)", analysis.getEstimatedSpaceComplexity());
    }

    @Test
    void testQuadraticComplexityDetection() {
        String quadraticCode = """
            public int[] solve(int[] nums, int target) {
                for (int i = 0; i < nums.length; i++) {
                    for (int j = i + 1; j < nums.length; j++) {
                        if (nums[i] + nums[j] == target) return new int[]{i, j};
                    }
                }
                return new int[]{};
            }
            """;
        ComplexityEstimator.ComplexityAnalysis analysis = estimator.estimateComplexity(quadraticCode, "JAVA");
        assertEquals("O(n²)", analysis.getEstimatedTimeComplexity());
        assertFalse(analysis.getSuggestions().isEmpty(), "Suggestions should advise optimizing nested loops");
    }
}

