export const OpponentCard = ({ opponent, lastEvent }) => {
  const [status, setStatus] = useState(opponent?.status || 'CODING');
  const [testsPassed, setTestsPassed] = useState(opponent?.testsPassed || 0);
  const [totalTests, setTotalTests] = useState(opponent?.totalTests || 0);
  const [disconnectTimer, setDisconnectTimer] = useState(30);

  useEffect(() => {
    if (opponent) {
      setStatus(opponent.status || 'CODING');
      setTestsPassed(opponent.testsPassed || 0);
      setTotalTests(opponent.totalTests || 0);
    }
  }, [opponent]);

  useEffect(() => {
    if (!lastEvent) return;

    if (lastEvent.type === 'PLAYER_CODING' && lastEvent.senderId === opponent?.userId) {
      if (status !== 'ACCEPTED') setStatus('CODING');
    } else if (lastEvent.type === 'PLAYER_RUNNING' && lastEvent.senderId === opponent?.userId) {
      setStatus('RUNNING');
    } else if (lastEvent.type === 'PLAYER_ACCEPTED' && lastEvent.senderId === opponent?.userId) {
      setStatus('ACCEPTED');
      if (lastEvent.data?.testsPassed) setTestsPassed(lastEvent.data.testsPassed);
      if (lastEvent.data?.totalTests) setTotalTests(lastEvent.data.totalTests);
    } else if (lastEvent.type === 'PLAYER_WRONG' && lastEvent.senderId === opponent?.userId) {
      setStatus('WRONG_ANSWER');
      if (lastEvent.data?.testsPassed) setTestsPassed(lastEvent.data.testsPassed);
      if (lastEvent.data?.totalTests) setTotalTests(lastEvent.data.totalTests);
    } else if (lastEvent.type === 'PLAYER_DISCONNECTED' && lastEvent.senderId === opponent?.userId) {
      setStatus('DISCONNECTED');
      setDisconnectTimer(30);
    } else if (lastEvent.type === 'PLAYER_RECONNECTED' && lastEvent.senderId === opponent?.userId) {
      setStatus('CODING');
    }
  }, [lastEvent, opponent?.userId, status]);

  // Handle Disconnection countdown
  useEffect(() => {
    if (status !== 'DISCONNECTED') return;

    const interval = setInterval(() => {
      setDisconnectTimer((prev) => (prev > 0 ? prev - 1 : 0));
    }, 1000);

    return () => clearInterval(interval);
  }, [status]);

  const getStatusBadge = () => {
    switch (status) {
      case 'RUNNING':
        return (
          <span className="flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-amber-500/20 text-amber-300 border border-amber-500/30 text-xs font-semibold animate-pulse">
            <Loader2 className="w-3.5 h-3.5 animate-spin" />
            <span>Running Code</span>
          </span>
        );
      case 'ACCEPTED':
        return (
          <span className="flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-emerald-500/20 text-emerald-300 border border-emerald-500/30 text-xs font-semibold neon-glow-emerald">
            <CheckCircle className="w-3.5 h-3.5 text-emerald-400" />
            <span>Accepted</span>
          </span>
        );
      case 'WRONG_ANSWER':
        return (
          <span className="flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-rose-500/20 text-rose-300 border border-rose-500/30 text-xs font-semibold">
            <XCircle className="w-3.5 h-3.5 text-rose-400" />
            <span>Wrong Answer</span>
          </span>
        );
      case 'TIME_LIMIT_EXCEEDED':
      case 'TLE':
        return (
          <span className="flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-orange-500/20 text-orange-300 border border-orange-500/30 text-xs font-semibold">
            <Clock className="w-3.5 h-3.5" />
            <span>Time Limit Exceeded</span>
          </span>
        );
      case 'DISCONNECTED':
        return (
          <span className="flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-slate-800 text-rose-400 border border-rose-500/40 text-xs font-semibold animate-pulse">
            <WifiOff className="w-3.5 h-3.5" />
            <span>Reconnecting ({disconnectTimer}s)</span>
          </span>
        );
      default:
        return (
          <span className="flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-emerald-950/40 text-emerald-400 border border-emerald-500/20 text-xs font-medium">
            <span className="w-2 h-2 rounded-full bg-emerald-400 animate-ping"></span>
            <span>Coding</span>
          </span>
        );
    }
  };

  return (
    <div className="bg-dark-800/90 border border-dark-600 rounded-2xl p-4 shadow-xl backdrop-blur-sm flex flex-col space-y-3">
      <div className="flex items-center justify-between">
        <div className="text-[11px] font-mono uppercase tracking-wider text-slate-400 font-bold flex items-center gap-1.5">
          <Activity className="w-3.5 h-3.5 text-cyan-400" />
          <span>Opponent Status</span>
        </div>
        {getStatusBadge()}
      </div>

      <div className="flex items-center space-x-3 bg-dark-900/60 p-3 rounded-xl border border-dark-700">
        <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-rose-500 to-amber-600 flex items-center justify-center font-bold text-white shadow-md">
          {opponent?.username?.charAt(0)?.toUpperCase() || 'O'}
        </div>
        <div className="flex-1 min-w-0">
          <div className="text-sm font-bold text-white truncate">{opponent?.username || 'Opponent'}</div>
          <div className="text-xs font-mono text-cyan-400 flex items-center gap-1 font-semibold">
            <span>Rating:</span>
            <span className="text-white">{opponent?.ratingBefore || 1500}</span>
          </div>
        </div>
      </div>

      {/* Progress Telemetry */}
      {totalTests > 0 && (
        <div className="space-y-1.5">
          <div className="flex justify-between text-xs text-slate-400">
            <span>Tests Passed:</span>
            <span className="font-mono font-bold text-slate-200">{testsPassed} / {totalTests}</span>
          </div>
          <div className="w-full h-2 bg-dark-900 rounded-full overflow-hidden border border-dark-700">
            <div
              className={`h-full transition-all duration-500 ${
                testsPassed === totalTests ? 'bg-emerald-500 neon-glow-emerald' : 'bg-cyan-500'
              }`}
              style={{ width: `${(testsPassed / totalTests) * 100}%` }}
            ></div>
          </div>
        </div>
      )}

      {status === 'DISCONNECTED' && (
        <div className="p-2.5 rounded-lg bg-rose-950/40 border border-rose-500/30 text-rose-300 text-xs flex items-center gap-2">
          <AlertTriangle className="w-4 h-4 flex-shrink-0" />
          <span>Opponent disconnected. If they fail to reconnect in {disconnectTimer}s, match will be awarded to you.</span>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Timer, AlertCircle } from 'lucide-react';

export const ServerTimer = ({ initialRemainingSeconds = 900, onTimeUp }) => {
  const [seconds, setSeconds] = useState(initialRemainingSeconds);

  useEffect(() => {
    setSeconds(initialRemainingSeconds);
  }, [initialRemainingSeconds]);

  useEffect(() => {
    if (seconds <= 0) {
      if (onTimeUp) onTimeUp();
      return;
    }

    const interval = setInterval(() => {
      setSeconds((prev) => {
        if (prev <= 1) {
          clearInterval(interval);
          if (onTimeUp) onTimeUp();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [seconds, onTimeUp]);

  const formatTime = (secs) => {
    const mins = Math.floor(secs / 60);
    const remainingSecs = secs % 60;
    return `${mins.toString().padStart(2, '0')}:${remainingSecs.toString().padStart(2, '0')}`;
  };

  const isLowTime = seconds < 180; // < 3 mins
  const isCriticalTime = seconds < 60; // < 1 min

  return (
    <div
      className={`flex items-center space-x-2 px-4 py-2 rounded-xl border transition-all duration-300 font-mono ${
        isCriticalTime
          ? 'bg-rose-950/40 border-rose-500/60 text-rose-400 animate-pulse neon-glow-rose'
          : isLowTime
          ? 'bg-amber-950/30 border-amber-500/40 text-amber-300'
          : 'bg-dark-800 border-dark-600 text-slate-200'
      }`}
    >
      <Timer className={`w-4 h-4 ${isCriticalTime ? 'text-rose-400 animate-spin' : isLowTime ? 'text-amber-400' : 'text-cyan-400'}`} />
      <span className="font-bold text-lg tracking-wider">
        {formatTime(seconds)}
      </span>
      {isCriticalTime && (
        <span className="text-[10px] font-sans font-bold bg-rose-500/30 text-rose-300 px-1.5 py-0.5 rounded">
          TIME RUNNING OUT
        </span>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import Editor from '@monaco-editor/react';
import { Play, Send, RotateCcw, Check, ChevronDown, Sparkles } from 'lucide-react';

const LANGUAGE_CONFIGS = {
  JAVA: { name: 'Java', monacoLang: 'java', defaultExt: 'java' },
  PYTHON: { name: 'Python 3', monacoLang: 'python', defaultExt: 'py' },
  CPP: { name: 'C++', monacoLang: 'cpp', defaultExt: 'cpp' },
  JAVASCRIPT: { name: 'JavaScript', monacoLang: 'javascript', defaultExt: 'js' },
};

export const MonacoCodeEditor = ({
  problemId,
  starterCodes = {},
  onSubmit,
  onRun,
  onTyping,
  submitting = false,
  running = false
}) => {
  const [selectedLanguage, setSelectedLanguage] = useState('PYTHON');
  const [code, setCode] = useState('');
  const [savedStatus, setSavedStatus] = useState('Saved');
  const typingTimerRef = useRef(null);

  // Load code from draft or starter code
  useEffect(() => {
    if (!problemId) return;

    const draftKey = `codeduel_draft_${problemId}_${selectedLanguage}`;
    const savedDraft = localStorage.getItem(draftKey);

    if (savedDraft) {
      setCode(savedDraft);
    } else if (starterCodes && starterCodes[selectedLanguage]) {
      setCode(starterCodes[selectedLanguage]);
    } else {
      // Generic starter
      if (selectedLanguage === 'PYTHON') {
        setCode('class Solution:\n    def solve(self, nums: list[int], target: int) -> list[int]:\n        # Write your solution here\n        pass\n');
      } else if (selectedLanguage === 'JAVA') {
        setCode('import java.util.*;\n\npublic class Solution {\n    public int[] solve(int[] nums, int target) {\n        // Write your solution here\n        return new int[]{};\n    }\n}\n');
      } else if (selectedLanguage === 'CPP') {
        setCode('#include <iostream>\n#include <vector>\nusing namespace std;\n\nclass Solution {\npublic:\n    vector<int> solve(vector<int>& nums, int target) {\n        // Write solution here\n        return {};\n    }\n};\n');
      } else {
        setCode('function solve(nums, target) {\n    // Write your solution here\n    return [];\n}\n');
      }
    }
  }, [problemId, selectedLanguage, starterCodes]);

  const handleEditorChange = (value) => {
    setCode(value || '');
    setSavedStatus('Saving...');

    if (problemId) {
      const draftKey = `codeduel_draft_${problemId}_${selectedLanguage}`;
      localStorage.setItem(draftKey, value || '');
      setTimeout(() => setSavedStatus('Saved draft'), 500);
    }

    // Fire typing event debounce
    if (onTyping) {
      if (typingTimerRef.current) clearTimeout(typingTimerRef.current);
      typingTimerRef.current = setTimeout(() => {
        onTyping();
      }, 400);
    }
  };

  const handleResetCode = () => {
    if (window.confirm('Reset code to initial template? Your current draft will be overwritten.')) {
      const defaultCode = starterCodes && starterCodes[selectedLanguage] ? starterCodes[selectedLanguage] : '';
      setCode(defaultCode);
      const draftKey = `codeduel_draft_${problemId}_${selectedLanguage}`;
      localStorage.removeItem(draftKey);
      setSavedStatus('Reset to template');
    }
  };

  const handleKeyDown = (e) => {
    if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
      e.preventDefault();
      if (!submitting && !running && onSubmit) {
        onSubmit(selectedLanguage, code);
      }
    }
  };

  return (
    <div className="flex flex-col h-full bg-dark-900 border border-dark-700 rounded-2xl overflow-hidden shadow-2xl" onKeyDown={handleKeyDown}>
      {/* Editor Header Bar */}
      <div className="flex items-center justify-between px-4 py-2.5 bg-dark-800 border-b border-dark-700">
        <div className="flex items-center space-x-3">
          {/* Language Selector */}
          <div className="relative">
            <select
              value={selectedLanguage}
              onChange={(e) => setSelectedLanguage(e.target.value)}
              className="bg-dark-900 text-xs font-semibold text-cyan-300 border border-dark-600 rounded-lg px-3 py-1.5 pr-8 appearance-none focus:outline-none focus:border-cyan-500 cursor-pointer"
            >
              {Object.entries(LANGUAGE_CONFIGS).map(([key, config]) => (
                <option key={key} value={key}>
                  {config.name}
                </option>
              ))}
            </select>
            <ChevronDown className="w-3.5 h-3.5 text-slate-400 absolute right-2.5 top-2.5 pointer-events-none" />
          </div>

          <span className="text-[11px] font-mono text-slate-400">
            {savedStatus}
          </span>
        </div>

        {/* Action Buttons */}
        <div className="flex items-center space-x-2">
          <button
            type="button"
            onClick={handleResetCode}
            title="Reset code"
            className="p-1.5 text-slate-400 hover:text-slate-200 hover:bg-dark-700 rounded-lg transition-colors"
          >
            <RotateCcw className="w-4 h-4" />
          </button>

          {onRun && (
            <button
              type="button"
              onClick={() => onRun(selectedLanguage, code)}
              disabled={running || submitting}
              className="flex items-center space-x-1.5 px-3 py-1.5 text-xs font-semibold text-slate-200 bg-dark-700 hover:bg-dark-600 rounded-lg border border-dark-500 transition-colors disabled:opacity-50"
            >
              <Play className="w-3.5 h-3.5 text-cyan-400 fill-cyan-400" />
              <span>{running ? 'Running...' : 'Run Code'}</span>
            </button>
          )}

          <button
            type="button"
            onClick={() => onSubmit(selectedLanguage, code)}
            disabled={submitting || running}
            className="flex items-center space-x-1.5 px-4 py-1.5 text-xs font-bold text-white bg-gradient-to-r from-indigo-600 to-cyan-600 hover:from-indigo-500 hover:to-cyan-500 rounded-lg shadow-lg shadow-indigo-600/30 transition-all duration-200 disabled:opacity-50"
          >
            <Send className="w-3.5 h-3.5" />
            <span>{submitting ? 'Judging...' : 'Submit (Ctrl+↵)'}</span>
          </button>
        </div>
      </div>

      {/* Monaco Editor Container */}
      <div className="flex-1 min-h-[350px] relative">
        <Editor
          height="100%"
          language={LANGUAGE_CONFIGS[selectedLanguage].monacoLang}
          value={code}
          theme="vs-dark"
          onChange={handleEditorChange}
          options={{
            fontSize: 13,
            fontFamily: "'Fira Code', monospace",
            minimap: { enabled: false },
            scrollBeyondLastLine: false,
            automaticLayout: true,
            tabSize: 4,
            padding: { top: 12, bottom: 12 },
            lineNumbersMinChars: 3,
            renderLineHighlight: 'all',
            cursorBlinking: 'smooth',
            smoothScrolling: true,
          }}
        />
      </div>
    </div>
  );
};

