            {problem.difficulty}
          </span>

          {problem.expectedTimeComplexity && (
            <span className="flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-mono bg-dark-800 text-cyan-300 border border-dark-600">
              <Clock className="w-3 h-3 text-cyan-400" />
              <span>Time: {problem.expectedTimeComplexity}</span>
            </span>
          )}

          {problem.expectedSpaceComplexity && (
            <span className="flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-mono bg-dark-800 text-indigo-300 border border-dark-600">
              <HardDrive className="w-3 h-3 text-indigo-400" />
              <span>Space: {problem.expectedSpaceComplexity}</span>
            </span>
          )}

          {problem.externalUrl && (
            <a
              href={problem.externalUrl}
              target="_blank"
              rel="noopener noreferrer"
              className="flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-sans text-slate-400 hover:text-cyan-300 bg-dark-800 hover:bg-dark-700 border border-dark-600 transition-colors ml-auto"
            >
              <span>View Original</span>
