                <span>Case {idx + 1} {tc.isHidden ? '(Hidden)' : ''}</span>
              </button>
            ))}
          </div>

          {/* Active Test Case Detail */}
          {testCases[activeTab] && (
            <div className="flex-1 p-4 overflow-y-auto space-y-3 font-mono text-xs">
              <div>
                <div className="text-slate-400 font-semibold mb-1">Input:</div>
                <div className="p-2.5 bg-dark-800 rounded-lg border border-dark-700 text-slate-200 whitespace-pre-wrap">
                  {testCases[activeTab].input}
                </div>
              </div>

              <div>
                <div className="text-slate-400 font-semibold mb-1">Expected Output:</div>
                <div className="p-2.5 bg-dark-800 rounded-lg border border-dark-700 text-emerald-400 whitespace-pre-wrap">
                  {testCases[activeTab].expected}
                </div>
              </div>

              <div>
                <div className="text-slate-400 font-semibold mb-1">Actual Output:</div>
                <div className={`p-2.5 rounded-lg border whitespace-pre-wrap ${
                  testCases[activeTab].passed
                    ? 'bg-dark-800 border-dark-700 text-emerald-300'
                    : 'bg-rose-950/30 border-rose-500/30 text-rose-300'
                }`}>
                  {testCases[activeTab].actual || '[No output or error]'}
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

