import { Swords, Radar, X, Zap, Shield, ChevronDown, Filter } from 'lucide-react';

const TOPIC_OPTIONS = [
  'All Topics',
  'Arrays & Hashing',
  'Two Pointers & Sliding Window',
  'Binary Search',
  'Strings',
  'Linked List',
  'Stack & Monotonic Stack',
