package com.codeduel.seed;

import com.codeduel.model.*;
import com.codeduel.repository.AchievementRepository;
import com.codeduel.repository.ProblemRepository;
import com.codeduel.repository.TestCaseRepository;
import com.codeduel.repository.UserRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.CommandLineRunner;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

import java.util.*;

@Component
public class ProblemSeeder implements CommandLineRunner {

    private static final Logger log = LoggerFactory.getLogger(ProblemSeeder.class);

    private final ProblemRepository problemRepository;
    private final TestCaseRepository testCaseRepository;
    private final UserRepository userRepository;
    private final AchievementRepository achievementRepository;
    private final PasswordEncoder passwordEncoder;

    public ProblemSeeder(ProblemRepository problemRepository,
                         TestCaseRepository testCaseRepository,
                         UserRepository userRepository,
                         AchievementRepository achievementRepository,
                         PasswordEncoder passwordEncoder) {
        this.problemRepository = problemRepository;
        this.testCaseRepository = testCaseRepository;
        this.userRepository = userRepository;
        this.achievementRepository = achievementRepository;
        this.passwordEncoder = passwordEncoder;
    }

    @Override
    @Transactional
    public void run(String... args) {
        seedInitialUsers();
        seedInitialAchievements();
        seed1000Problems();
    }

    private void seedInitialUsers() {
        if (userRepository.count() == 0) {
            log.info("Seeding initial users...");

            User admin = new User("admin", "admin@codeduel.dev", passwordEncoder.encode("admin123"), Role.ROLE_ADMIN);
            admin.setRating(2100);
            admin.setWins(150);
            admin.setLosses(25);
            admin.setMatchesPlayed(175);
            admin.setWinStreak(8);
            admin.setBestWinStreak(14);
            admin.setGlobalRank(1);

            User anshu = new User("anshu", "anshu@codeduel.dev", passwordEncoder.encode("password123"), Role.ROLE_USER);
            anshu.setRating(1542);
            anshu.setWins(42);
            anshu.setLosses(20);
            anshu.setMatchesPlayed(62);
            anshu.setWinStreak(5);
            anshu.setBestWinStreak(9);
            anshu.setGlobalRank(248);

            User rahul = new User("rahul", "rahul@codeduel.dev", passwordEncoder.encode("password123"), Role.ROLE_USER);
            rahul.setRating(1518);
            rahul.setWins(38);
            rahul.setLosses(22);
            rahul.setMatchesPlayed(60);
            rahul.setWinStreak(2);
            rahul.setBestWinStreak(7);
            rahul.setGlobalRank(265);

            User aman = new User("aman", "aman@codeduel.dev", passwordEncoder.encode("password123"), Role.ROLE_USER);
            aman.setRating(1791);
            aman.setWins(110);
            aman.setLosses(45);
            aman.setMatchesPlayed(155);
            aman.setWinStreak(4);
            aman.setBestWinStreak(12);
            aman.setGlobalRank(3);

            userRepository.saveAll(Arrays.asList(admin, anshu, rahul, aman));
            log.info("Initial users seeded successfully.");
        }
    }

    private void seedInitialAchievements() {
        if (achievementRepository.count() == 0) {
            log.info("Seeding initial achievements...");
            List<Achievement> achievements = Arrays.asList(
                    new Achievement("FIRST_WIN", "First Blood", "Win your first 1v1 Versus match", "Trophy", "MATCHES", 50),
                    new Achievement("WINS_10", "Decathlete", "Win 10 Versus matches", "Award", "MATCHES", 100),
                    new Achievement("WINS_50", "Gladiator", "Win 50 Versus matches", "Shield", "MATCHES", 250),
                    new Achievement("WINS_100", "Grand Champion", "Win 100 Versus matches", "Crown", "MATCHES", 500),
                    new Achievement("STREAK_5", "On Fire", "Achieve a 5-match win streak", "Flame", "STREAK", 150),
                    new Achievement("STREAK_10", "Unstoppable", "Achieve a 10-match win streak", "Zap", "STREAK", 300),
                    new Achievement("BEAT_HIGHER_RATED", "Giant Slayer", "Defeat an opponent rated 100+ points above you", "Crosshair", "RATING", 200),
                    new Achievement("PERFECT_EFFICIENCY", "Code Virtuoso", "Achieve an efficiency score of 95+ in a match", "Sparkles", "EFFICIENCY", 200),
                    new Achievement("SPEED_DEMON", "Speed Demon", "Submit an accepted solution within 2 minutes", "Timer", "EFFICIENCY", 150),
                    new Achievement("ALGO_MASTER", "Algorithm Master", "Solve at least 50 Hard difficulty problems", "Cpu", "MASTERY", 500)
            );
            achievementRepository.saveAll(achievements);
            log.info("Achievements seeded successfully.");
        }
    }

    private void seed1000Problems() {
        Optional<Problem> p2 = problemRepository.findBySlug("contains-duplicate");
        if (p2.isPresent() && p2.get().getStarterCodeJava().contains("boolean solve(int[] nums)")) {
            log.info("Question bank already up to date with exact LeetCode signatures and testcases.");
            return;
        }

        log.info("Seeding authentic LeetCode problems with matched signatures and test cases...");
        testCaseRepository.deleteAll();
        problemRepository.deleteAll();

        List<TopicBlueprint> blueprints = Arrays.asList(
                new TopicBlueprint("Arrays & Hashing", "Array,Hash Table", "Hashing,Prefix Sum,Frequency Maps,Kadane", 120, 30, 66, 24),
                new TopicBlueprint("Two Pointers & Sliding Window", "Array,Two Pointers,Sliding Window", "Two Pointers,Sliding Window", 80, 20, 44, 16),
                new TopicBlueprint("Binary Search", "Array,Binary Search", "Binary Search,Search Space Reduction", 70, 18, 38, 14),
                new TopicBlueprint("Strings", "String,Hash Table", "String Matching,Two Pointers,Frequency", 70, 20, 38, 12),
                new TopicBlueprint("Linked List", "Linked List,Two Pointers", "Fast & Slow Pointers,Reversal,Merge", 60, 18, 32, 10),
                new TopicBlueprint("Stack & Monotonic Stack", "Stack,Monotonic Stack", "Monotonic Stack,Parentheses,Evaluation", 60, 16, 32, 12),
                new TopicBlueprint("Queue & Deque", "Queue,Deque,Sliding Window", "Monotonic Queue,BFS Queue,Circular Buffer", 30, 8, 16, 6),
                new TopicBlueprint("Trees & BST", "Tree,Binary Tree,Binary Search Tree", "DFS,BFS,Recursion,Tree DP", 100, 25, 55, 20),
                new TopicBlueprint("Heap / Priority Queue", "Heap (Priority Queue),Array", "Top K Elements,K-Way Merge,Min-Max Heap", 50, 12, 28, 10),
                new TopicBlueprint("Greedy", "Greedy,Sorting,Array", "Greedy Choice,Interval Scheduling,Partitioning", 60, 15, 33, 12),
                new TopicBlueprint("Backtracking", "Backtracking,Recursion", "State Exploration,Pruning,Permutations", 40, 8, 22, 10),
                new TopicBlueprint("Graphs", "Graph,Breadth-First Search,Depth-First Search,Union Find", "BFS,DFS,Dijkstra,Topological Sort,DSU,MST", 120, 26, 68, 26),
                new TopicBlueprint("Dynamic Programming", "Dynamic Programming", "1D DP,2D DP,Knapsack,Subsequence DP,Grid DP", 130, 24, 72, 34),
                new TopicBlueprint("Bit Manipulation", "Bit Manipulation,Math", "Bitwise XOR,Bit Masking,Bit Counting", 40, 12, 20, 8),
                new TopicBlueprint("Trie", "Trie,String,Design", "Prefix Tree,Bitwise Trie,Autocomplete", 20, 4, 12, 4),
                new TopicBlueprint("Advanced Data Structures & Algorithms", "Segment Tree,Binary Indexed Tree,Graph,Math", "Range Queries,Flow,Matrix Exponentiation", 50, 4, 26, 20)
        );

        int problemCounter = 1;
        List<Problem> problemBatch = new ArrayList<>();
        List<TestCase> testCaseBatch = new ArrayList<>();

        for (TopicBlueprint bp : blueprints) {
            int easyAllocated = 0;
            int medAllocated = 0;
            int hardAllocated = 0;

            for (int i = 1; i <= bp.totalCount; i++) {
                String problemId = String.format("CD-%04d", problemCounter);
                Difficulty diff;
                if (easyAllocated < bp.easyCount) {
                    diff = Difficulty.EASY;
                    easyAllocated++;
                } else if (medAllocated < bp.mediumCount) {
                    diff = Difficulty.MEDIUM;
                    medAllocated++;
                } else {
                    diff = Difficulty.HARD;
                    hardAllocated++;
                }

                String title = getCuratedProblemTitle(bp.category, i, diff);
                String slug = getCanonicalSlug(title, problemCounter);

                Problem problem = new Problem();
                problem.setId(problemId);
                problem.setTitle(title);
                problem.setSlug(slug);
                problem.setDifficulty(diff);
                problem.setTopics(bp.topics);
                problem.setPatterns(bp.patterns);
                problem.setDescription(getCuratedDescription(title, bp.category, diff));
                problem.setConstraints(getCuratedConstraints(title, diff));
                problem.setExamples(getCuratedExamples(title, bp.category));
                problem.setHints(getCuratedHints(title, bp.category));
                problem.setEditorial(getCuratedEditorial(title, bp.category, diff));
                problem.setInputFormat("Standard competitive programming format as specified in problem statement.");
                problem.setOutputFormat("Return the expected calculated answer value.");
                problem.setTimeLimitMs(diff == Difficulty.HARD ? 3000 : 2000);
                problem.setMemoryLimitMb(256);
                problem.setExpectedTimeComplexity(getExpectedTimeComplexity(bp.category, diff));
                problem.setExpectedSpaceComplexity(getExpectedSpaceComplexity(bp.category, diff));
                problem.setSource("LeetCode");
                problem.setExternalUrl("https://leetcode.com/problems/" + slug + "/");
                problem.setStarterCodeJava(generateStarterCodeJava(title));
                problem.setStarterCodePython(generateStarterCodePython(title));
                problem.setStarterCodeCpp(generateStarterCodeCpp(title));
                problem.setStarterCodeJs(generateStarterCodeJs(title));
                problem.setSolutionExplanation(getCuratedEditorial(title, bp.category, diff));
                problem.setIsActive(true);
                problem.setTotalSubmissions(35 + (problemCounter * 3) % 200);
                problem.setAcceptedSubmissions(18 + (problemCounter * 2) % 120);
                problem.setAvgRuntimeMs(diff == Difficulty.EASY ? 85.0 : diff == Difficulty.MEDIUM ? 145.0 : 260.0);
                problem.setAvgMemoryMb(diff == Difficulty.EASY ? 18.5 : diff == Difficulty.MEDIUM ? 26.4 : 38.2);

                problemBatch.add(problem);

                // Add problem-specific matched test cases
                List<TestCase> cases = generateTestCasesForProblem(problem, title);
                testCaseBatch.addAll(cases);

                problemCounter++;
            }
        }

        problemRepository.saveAll(problemBatch);
        testCaseRepository.saveAll(testCaseBatch);

        log.info("Successfully seeded {} total DSA problems into CodeDuel bank! (Target: 1000)", problemBatch.size());
    }

    private String getCanonicalSlug(String title, int counter) {
        return switch (title) {
            case "Two Sum" -> "two-sum";
            case "Contains Duplicate" -> "contains-duplicate";
            case "Valid Anagram" -> "valid-anagram";
            case "Group Anagrams" -> "group-anagrams";
            case "Top K Frequent Elements" -> "top-k-frequent-elements";
            case "Product of Array Except Self" -> "product-of-array-except-self";
            case "Valid Palindrome" -> "valid-palindrome";
            case "3Sum" -> "3sum";
            case "Container With Most Water" -> "container-with-most-water";
            case "Best Time to Buy and Sell Stock" -> "best-time-to-buy-and-sell-stock";
            case "Longest Substring Without Repeating Characters" -> "longest-substring-without-repeating-characters";
            case "Binary Search" -> "binary-search";
            case "Search in Rotated Sorted Array" -> "search-in-rotated-sorted-array";
            case "Climbing Stairs" -> "climbing-stairs";
            case "Coin Change" -> "coin-change";
            case "Maximum Subarray" -> "maximum-subarray";
            case "Invert Binary Tree" -> "invert-binary-tree";
            case "Number of Islands" -> "number-of-islands";
            default -> title.toLowerCase().replaceAll("[^a-z0-9]+", "-").replaceAll("^-|-$", "") + "-" + counter;
        };
    }

    private List<TestCase> generateTestCasesForProblem(Problem problem, String title) {
        List<TestCase> list = new ArrayList<>();
        if ("Contains Duplicate".equalsIgnoreCase(title)) {
            list.add(new TestCase(problem, "4\n1 2 3 1", "true", false, 1));
            list.add(new TestCase(problem, "4\n1 2 3 4", "false", false, 2));
