    private String getCuratedEditorial(String title, String category, Difficulty diff, SignatureType sigType) {
        if ("Two Sum".equalsIgnoreCase(title)) {
            return "### Overview\n" +
                    "The problem asks us to find two distinct indices in an array `nums` such that their values sum to `target`.\n\n" +
                    "### Approach: One-Pass Hash Table (Optimal)\n" +
                    "While we iterate and insert elements into a Hash Map, we also look back to check if current element's complement (`target - num`) already exists in the table.\n\n" +
                    "```python\n" +
                    "class Solution:\n" +
                    "    def solve(self, nums: list[int], target: int) -> list[int]:\n" +
                    "        seen = {}\n" +
                    "        for i, num in enumerate(nums):\n" +
                    "            comp = target - num\n" +
                    "            if comp in seen:\n" +
                    "                return [seen[comp], i]\n" +
                    "            seen[num] = i\n" +
                    "        return []\n" +
                    "```\n\n" +
                    "- **Time Complexity**: $O(n)$\n" +
                    "- **Space Complexity**: $O(n)$";
        }
        if ("Contains Duplicate".equalsIgnoreCase(title)) {
            return "### Overview\n" +
                    "Return `true` if any value appears at least twice in the array.\n\n" +
                    "### Approach: Hash Set (Optimal)\n" +
                    "Iterate through the array and insert each element into a `HashSet`. If the element is already present, return `true` immediately.\n\n" +
                    "```python\n" +
                    "class Solution:\n" +
                    "    def solve(self, nums: list[int]) -> bool:\n" +
                    "        seen = set()\n" +
                    "        for num in nums:\n" +
                    "            if num in seen:\n" +
                    "                return True\n" +
                    "            seen.add(num)\n" +
                    "        return False\n" +
                    "```\n\n" +
                    "- **Time Complexity**: $O(n)$\n" +
                    "- **Space Complexity**: $O(n)$";
        }

        return "### Algorithmic Approach\n" +
                "Solve this problem using optimal **" + category + "** techniques.\n\n" +
                "### Complexity Analysis\n" +
                "- **Time Complexity**: $O(" + getExpectedTimeComplexity(category, diff) + ")$\n" +
                "- **Space Complexity**: $O(" + getExpectedSpaceComplexity(category, diff) + ")$";
    }

    private String getExpectedTimeComplexity(String category, Difficulty diff) {
        if ("Binary Search".equals(category)) return "log n";
        if ("Arrays & Hashing".equals(category) || "Two Pointers & Sliding Window".equals(category) || "Strings".equals(category) || "Linked List".equals(category) || "Bit Manipulation".equals(category)) {
            return diff == Difficulty.HARD ? "n log n" : "n";
        }
        if ("Trees & BST".equals(category) || "Graphs".equals(category)) {
            return "V + E";
        }
        if ("Dynamic Programming".equals(category)) {
            return diff == Difficulty.HARD ? "n * m" : "n";
        }
        return "n log n";
    }

    private String getExpectedSpaceComplexity(String category, Difficulty diff) {
        if ("Bit Manipulation".equals(category) || "Two Pointers & Sliding Window".equals(category)) return "1";
        if ("Dynamic Programming".equals(category)) return diff == Difficulty.EASY ? "1" : "n";
        return "n";
    }

